const body = $input.first().json.body;
const required = ['invoice_id', 'client_name', 'client_email', 'amount', 'currency', 'due_date', 'your_name'];
const missing = required.filter(f => !body[f]);
if (missing.length) return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
const amount = parseFloat(body.amount);
if (isNaN(amount) || amount <= 0) return [{ json: { valid: false, error: 'amount must be a positive number' } }];
const dueDate = new Date(body.due_date);
if (isNaN(dueDate)) return [{ json: { valid: false, error: 'due_date must be valid (YYYY-MM-DD)' } }];
const today = new Date(); today.setHours(0,0,0,0);
const daysOverdue = Math.floor((today - dueDate) / 86400000);
const tones = ['gentle', 'firm', 'urgent', 'final_notice'];
let tone = body.tone || 'gentle';
if (!tones.includes(tone)) {
  if (daysOverdue <= 7) tone = 'gentle';
  else if (daysOverdue <= 21) tone = 'firm';
  else if (daysOverdue <= 45) tone = 'urgent';
  else tone = 'final_notice';
}
return [{ json: {
  valid: true,
  invoiceId: body.invoice_id.trim(),
  clientName: body.client_name.trim(),
  clientEmail: body.client_email.trim(),
  amount, currency: body.currency,
  dueDate: body.due_date,
  daysOverdue: Math.max(0, daysOverdue),
  yourName: body.your_name.trim(),
  yourCompany: body.your_company || '',
  yourEmail: body.your_email || '',
  projectDescription: (body.project_description || '').slice(0, 200),
  paymentInstructions: (body.payment_instructions || '').slice(0, 300),
  previousChaseCount: parseInt(body.previous_chase_count) || 0,
  tone,
  includeLateFee: body.include_late_fee === true || body.include_late_fee === 'true',
  lateFeeAmount: parseFloat(body.late_fee_amount) || null,
  sendEmail: body.send_email !== false,
  replyEmail: body.reply_email || null
} }];

