const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let chase;
try { chase = JSON.parse(raw.replace(/```json|```/g,'').trim()); } catch(e) { return [{ json: { error: 'Parse error', raw } }]; }
const input = $('Validate Input').first().json;
chase._invoice = input;
return [{ json: chase }];

const rows = $input.all().map(r => r.json).filter(r => r.invoice_id && r.status !== 'paid');
const today = new Date(); today.setHours(0,0,0,0);
const overdue = rows.map(r => {
  const due = new Date(r.due_date);
  const daysOverdue = Math.floor((today - due) / 86400000);
  return { ...r, daysOverdue };
}).filter(r => r.daysOverdue > 0);
return overdue.map(r => ({ json: r }));

const r = $input.first().json;
const d = r.daysOverdue;
const prev = parseInt(r.previous_chase_count) || 0;
let tone = r.tone_override || '';
if (!tone) {
  if (d <= 7) tone = 'gentle';
  else if (d <= 21) tone = 'firm';
  else if (d <= 45) tone = 'urgent';
  else tone = 'final_notice';
}
return [{ json: { invoiceId: r.invoice_id, clientName: r.client_name, clientEmail: r.client_email, amount: parseFloat(r.amount), currency: r.currency||'USD', dueDate: r.due_date, daysOverdue: d, yourName: r.your_name||'', yourCompany: r.your_company||'', yourEmail: r.your_email||'', projectDescription: r.project_description||'', paymentInstructions: r.payment_instructions||'', previousChaseCount: prev, tone, includeLateFee: r.include_late_fee==='true'||r.include_late_fee===true, lateFeeAmount: parseFloat(r.late_fee_amount)||null, sendEmail: r.auto_chase==='true'||r.auto_chase===true } }];

